                <a aria-label="DX UI home" className="flex items-center gap-2" href="/">
                  <img
                    alt=""
                    aria-hidden="true"
                    className="size-6"
                    draggable={false}
                    height={24}
                    src="/brand/dx-mark-128.webp"
                    width={24}
                  />
                  <span className="font-medium text-[15px] tracking-[-0.02em]">
                    DX <span className="text-muted-foreground">UI</span>
                  </span>
                </a>

                <button
                  aria-label={menuState === true ? "Close Menu" : "Open Menu"}
                  className="relative z-20 -m-2.5 -mr-4 block cursor-pointer p-2.5 lg:hidden"
                  onClick={() => setMenuState(!menuState)}
                  type="button"
                >
                  <AnimatePresence mode="wait">
                    {menuState ? (
                      <motion.div
                        animate={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : { opacity: 1, rotate: 0, scale: SCALE_MAX }
                        }
                        exit={
                          shouldReduceMotion
                            ? { opacity: 0, transition: { duration: 0 } }
                            : {
                                opacity: 0,
                                rotate: -ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        initial={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : {
                                opacity: 0,
                                rotate: ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        key="close"
                        transition={
                          shouldReduceMotion
                            ? { duration: 0 }
                            : {
                                duration: ANIMATION_DURATION,
                                ease: EASE_OUT_QUART,
                              }
                        }
                      >
                        <X className="m-auto size-6" />
                      </motion.div>
                    ) : (
                      <motion.div
                        animate={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : { opacity: 1, rotate: 0, scale: SCALE_MAX }
                        }
                        exit={
                          shouldReduceMotion
                            ? { opacity: 0, transition: { duration: 0 } }
                            : {
                                opacity: 0,
                                rotate: ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        initial={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : {
                                opacity: 0,
                                rotate: -ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        key="menu"
                        transition={
                          shouldReduceMotion
                            ? { duration: 0 }
                            : {
                                duration: ANIMATION_DURATION,
                                ease: EASE_OUT_QUART,
                              }
                        }
                      >
                        <Menu className="m-auto size-6" />
                      </motion.div>
                    )}
                  </AnimatePresence>
                </button>

                <div className="m-auto hidden size-fit lg:block">
                  <ul className="flex gap-1">
                    {menuItems.map((item) => (
                      <li key={item.id}>
                        <PressButton asChild size="sm" variant="ghost">
                          <a className="text-base" href={item.href}>
                            <span>{item.name}</span>
                          </a>
                        </PressButton>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              <AnimatePresence>
                {menuState ? (
                  <motion.div
                    animate={
                      shouldReduceMotion
                        ? { opacity: 1 }
                        : { opacity: 1, scale: SCALE_MAX, y: 0 }
                    }
                    className="mb-6 w-full flex-wrap items-center justify-end space-y-8 rounded-3xl border bg-background p-6 shadow-2xl shadow-zinc-300/20 md:flex-nowrap lg:m-0 lg:flex lg:w-fit lg:gap-6 lg:space-y-0 lg:border-transparent lg:bg-transparent lg:p-0 lg:shadow-none dark:shadow-none dark:lg:bg-transparent"
                    exit={
                      shouldReduceMotion
                        ? { opacity: 0, transition: { duration: 0 } }
                        : { opacity: 0, scale: 0.95, y: TRANSLATE_Y_OFFSET }
                    }
                    initial={
                      shouldReduceMotion
                        ? { opacity: 1 }
                        : { opacity: 0, scale: 0.95, y: TRANSLATE_Y_OFFSET }
                    }
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : {
                            duration: ANIMATION_DURATION,
                            ease: EASE_OUT_QUART,
                          }
                    }
                  >
                    <div className="lg:hidden">
                      <ul className="space-y-6 text-base">
                        {menuItems.map((item, index) => (
                          <motion.li
                            animate={
                              shouldReduceMotion
                                ? { opacity: 1 }
                                : { opacity: 1, x: 0 }
                            }
                            initial={
                              shouldReduceMotion
                                ? { opacity: 1 }
                                : { opacity: 0, x: TRANSLATE_X_OFFSET }
                            }
                            key={item.id}
                            transition={
                              shouldReduceMotion
                                ? { duration: 0 }
                                : {
                                    delay: index * STAGGER_DELAY,
                                    duration: ANIMATION_DURATION,
                                    ease: EASE_OUT_QUART,
                                  }
                            }
                          >
                            <a
                              className="block text-muted-foreground duration-150 hover:text-accent-foreground"
                              href={item.href}
                              onClick={() => setMenuState(false)}
                            >
                              <span>{item.name}</span>
                            </a>
                          </motion.li>
                        ))}
                      </ul>
                    </div>
                    <motion.div
                      animate={
                        shouldReduceMotion
                          ? { opacity: 1 }
                          : { opacity: 1, y: 0 }
                      }
                      className="flex w-full flex-col space-y-3 sm:flex-row sm:gap-3 sm:space-y-0 md:w-fit"
                      initial={
                        shouldReduceMotion
                          ? { opacity: 1 }
                          : { opacity: 0, y: 10 }
                      }
                      transition={
                        shouldReduceMotion
                          ? { duration: 0 }
                          : {
                              delay:
                                menuItems.length * STAGGER_DELAY +
                                STAGGER_DELAY,
                              duration: ANIMATION_DURATION,
                              ease: EASE_OUT_QUART,
                            }
                      }
                    >
                      <PressButton
                        onClick={() => setMenuState(false)}
                        size="sm"
                        type="button"
                        variant="ghost"
                      >
                        <span>Login</span>
                      </PressButton>
                      <PressButton
                        onClick={() => setMenuState(false)}
                        size="sm"
                        type="button"
                      >
                        <span>Sign Up</span>
                      </PressButton>
                    </motion.div>
                  </motion.div>
                ) : null}
              </AnimatePresence>
            </div>
          </div>
        </nav>
      </header>
    </div>
  );
};
